// Package javamath computes the java.lang.Math functions whose results Java 21 on x86_64
// rounds differently from Go's math package, bit for bit as production computes them.
// Positions store full-precision results (distance, totalDistance), so a last-bit
// difference would show up in the database.
//
// Math.sin and Math.cos are HotSpot intrinsics on x86_64: Go runs the same stub code on an
// emulated machine (libm_gen.go, generated by ./gen; x86.go). Math.atan2 is StrictMath's
// fdlibm algorithm (fdlibm.go). Math.sqrt is correctly rounded in both languages, so
// math.Sqrt is already exact.
package javamath

//go:generate sh -c "go run ./gen -src \"$HOTSPOT_SRC\" > libm_gen.go"

// Sin is Math.sin.
func Sin(x float64) float64 { return libmSin(x) }

// Cos is Math.cos.
func Cos(x float64) float64 { return libmCos(x) }

// Atan2 is Math.atan2 (StrictMath.atan2).
func Atan2(y, x float64) float64 { return atan2(y, x) }
